local BLOCK_ANIMS_WHEN_ATTACHED = {

    [_a("britadeira")] = true
}

RegisterCommand( 'e', function( _, args, raw )
    local Ped = PlayerPedId()
	-- Esse comando foi desabilitado?
	if LocalPlayer.state[ 'Buttons' ] then
        return
    end

    if BLOCK_ANIMS_WHEN_ATTACHED[args[1]] then

        if IsEntityAttached(Ped) then

            TriggerEvent( 'Notify', 'vermelho', _t("emotes_incapacitated") )

            return
        end
    end

    if IsPedFalling(Ped) then
        return
    end

    if exports.combatsystem:IsInCombat( { showHint = true } ) then

        -- is combat active ?

        return
    end

	if not CanPedPlayEmotes( PlayerPedId() ) then

		TriggerEvent( 'Notify', 'vermelho', _t("emotes_incapacitated") )

		return
	end

	---@type EmoteId | nil
	local emoteId = args[ 1 ]

	-- print( '/e :: emoteId=', emoteId )

	if not emoteId then

		TriggerEvent( 'Notify', 'vermelho', _t("emotes_specify_animation") )

		return
	end

    emoteId = emoteId:lower()

	local pairedEmote = PAIRED_EMOTE_BY_ID[ emoteId ]

	if pairedEmote then

		-- O outro jogador com quem a gente vai executar esse emote.
		local pairedSource = vRP.ClosestPed( 1.0 )

		-- print( '/e :: pairedSource=', pairedSource )

		if not pairedSource then

			TriggerEvent( 'Notify', 'vermelho', _t("emotes_need_partner") )

			return
		end

		local pairedPedId = GetPlayerPed( NetworkGetPlayerIndex( pairedSource ) )

		if not CanPedPlayEmotes( pairedPedId ) then

			TriggerEvent( 'Notify', 'vermelho', _t("emotes_partner_incapacitated") )
	
			return
		end

		TriggerServerEvent(  'net:emotes:request_play_paired_emote', emoteId, pairedSource )

		return
	end

	TriggerEvent( 'emotes', emoteId )
end)

-----------------------------------------------------------------------------------------------------------------------------------------
-- THREAD: Animações com blockWeapons bloqueiam atirar
-----------------------------------------------------------------------------------------------------------------------------------------

-- Pre-built list com todas as animações que bloqueiam armas (Animations + extras).
-- Evita iterar os 3000+ entries de Animations a cada tick.
local ALL_BLOCK_ANIMS = {
	{ "missminuteman_1ig_2", "handsup_base" },
    { "anim@mp_point", " intro_0" },
    { "mini@strip_club@idles@bouncer@base","base" },
    { "anim@mp_player_intupperfinger","idle_a_fp" },
}
for _, v in pairs(Animations) do
	if v.blockWeapons and v.dict and v.anim then
		ALL_BLOCK_ANIMS[#ALL_BLOCK_ANIMS + 1] = { v.dict, v.anim }
	end
end

-- Slow thread: check blocking anims every 200ms, cache result
local isBlockingAnim = false
CreateThread(function()
	while true do
		local Ped = PlayerPedId()
		local blocking = false

		for _, t in ipairs(ALL_BLOCK_ANIMS) do
			if IsEntityPlayingAnim(Ped, t[1], t[2], 3) then
				blocking = true
				break
			end
		end

		isBlockingAnim = blocking
		Wait(200)
	end
end)

-- Fast thread: disable controls per-frame only when needed
CreateThread(function()
	while true do
		if isBlockingAnim or IsTaskMoveNetworkActive(PlayerPedId()) ~= false then
			DisableControlAction(1, 24, true)
			DisableControlAction(1, 25, true)
			DisableControlAction(1, 257, true)
			DisableControlAction(1, 263, true)
			DisableControlAction(1, 140, true)
			DisableControlAction(1, 142, true)
			DisableControlAction(1, 143, true)
			DisablePlayerFiring(PlayerPedId(), true)
			Wait(0)
		else
			Wait(200)
		end
	end
end)

