--[[
    Essas partes de: [LIST_ANIMATIONS_BLOCK_CONDITIONS] [BlockAnimationExecute]
    - Isso foi criado para evitar que certas animações afetem visualmente a gameplay de outros players

    Exemplo: Ao usar o bailar9 quando cai do carro, o player fica deslizando em pé, bugando o /wall e a visão dos players.
    Isso: isso apenas acontece ao dar play na animação apos cair do carro (até o momento).

    Daria para simplesmente colocar isso no evento que da play na animação, mas prefiro deixar separado. Caso a gente precise alterar algo, só alterar aqui.
    [LIST_ANIMATIONS_BLOCK_CONDITIONS]

    -- Possivel fix falamos em call (key_value) e (utinhasz):
       Se não for possivel usar uma flag ou algo do tipo, podemos pegar na tabela a informação walk = false e fazer isso:
        Posição que ele começou a animação e a posição atual, e criar um range, caso o player saia fora do range a gente pode cancelar a animação.
]]

local LIST_ANIMATIONS_BLOCK_CONDITIONS = {
    [_a("bailar9")] = {
        gettingUp = true,
        ragdoll = true
    }
}

---@param name string
local function BlockAnimationExecute(name)
    local animation = LIST_ANIMATIONS_BLOCK_CONDITIONS[name]

    if not animation then
        return false
    end

    local player = PlayerPedId()

    if animation.gettingUp and IsPedGettingUp(player) then -- caso o player esteja levantando após cair
        return true
    end

    if animation.ragdoll and IsPedRagdoll(player) then -- caso o player esteja ragdoll
        return true
    end

    return false
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- EMOTES
-----------------------------------------------------------------------------------------------------------------------------------------
local animCooldown = GetGameTimer()
RegisterNetEvent("emotes")
AddEventHandler("emotes",function(name,sync)
    local Ped = PlayerPedId()
    if LocalPlayer["state"]["Buttons"] then
        return
    end
    if IsPedInScriptedPvpAnimationBlock(Ped) then
        return
    end
    if IsPedDrivingVehicle(Ped) then
        return
    end

    if GetGameTimer() < animCooldown then
        return
    end

    if IsPedFalling(Ped) then
        return
    end

    if string.find(name,"fumar") then
        animCooldown = GetGameTimer() + 2500
    end

    -- if name == _a("lutar29") then
    --     animCooldown = GetGameTimer() + 2000
    -- end

    if BlockAnimationExecute(name) then
        return
    end

	if not LocalPlayer["state"]["Commands"] and not LocalPlayer["state"]["Handcuff"] then
        
		if Animations[name] and not IsPedSwimming(Ped) then
			if GetEntityHealth(Ped) > 100 and vINVENTORY.checkInventory() then
                
                if Animations[name]["anim"] == "WORLD_HUMAN_PARTYING" then
                    animCooldown = GetGameTimer() + 7500
                end
                
				TriggerEvent("vrp:removeObjects","one")
                
				if not IsPedInAnyVehicle(Ped) and not Animations[name]["cars"] then
					if Animations[name]["extra"] then
						Animations[name].extra()
					end
					if Animations[name]["scriptedInteraction"] then
						local siName = Animations[name]["scriptedInteraction"]
						local ok, err = pcall( function()
							exports.scripted_interactions:startScriptedInteraction( siName )
						end )
						if not ok and sx and sx.logger then
							sx.logger:warn( ( 'animacoes: startScriptedInteraction(%s) failed: %s' ):format( tostring( siName ), tostring( err ) ) )
						end
					elseif sync then
                        if Animations[name]["target"]["pos1"] and not Animations[name]["target"]["anim"] then
                            TriggerEvent("vrp:createObjects","","",Animations[name]["target"]["prop"],Animations[name]["target"]["flag"],Animations[name]["target"]["hand"],Animations[name]["target"]["pos1"],Animations[name]["target"]["pos2"],Animations[name]["target"]["pos3"],Animations[name]["target"]["pos4"],Animations[name]["target"]["pos5"],Animations[name]["target"]["pos6"])
                        elseif Animations[name]["target"]["pos1"] and Animations[name]["target"]["anim"] then
                            TriggerEvent("vrp:createObjects",Animations[name]["target"]["dict"],Animations[name]["target"]["anim"],Animations[name]["target"]["prop"],Animations[name]["target"]["flag"],Animations[name]["target"]["hand"],Animations[name]["target"]["pos1"],Animations[name]["target"]["pos2"],Animations[name]["target"]["pos3"],Animations[name]["target"]["pos4"],Animations[name]["target"]["pos5"],Animations[name]["target"]["pos6"])
                        elseif Animations[name]["target"]["prop"] then
                            TriggerEvent("vrp:createObjects",Animations[name]["target"]["dict"],Animations[name]["target"]["anim"],Animations[name]["target"]["prop"],Animations[name]["target"]["flag"],Animations[name]["target"]["hand"])
                        elseif Animations[name]["target"]["dict"] then
                            vRP.playAnim(Animations[name]["target"]["walk"],{Animations[name]["target"]["dict"],Animations[name]["target"]["anim"]},Animations[name]["target"]["loop"])
                        else
                            vRP.playAnim(false,{ task = Animations[name]["target"]["anim"] },false)
                        end
                    else
                        if Animations[name]["pos1"] and not Animations[name]["anim"] then
                            TriggerEvent("vrp:createObjects","","",Animations[name]["prop"],Animations[name]["flag"],Animations[name]["hand"],Animations[name]["pos1"],Animations[name]["pos2"],Animations[name]["pos3"],Animations[name]["pos4"],Animations[name]["pos5"],Animations[name]["pos6"])
                        elseif Animations[name]["pos1"] and Animations[name]["anim"] then
                            TriggerEvent("vrp:createObjects",Animations[name]["dict"],Animations[name]["anim"],Animations[name]["prop"],Animations[name]["flag"],Animations[name]["hand"],Animations[name]["pos1"],Animations[name]["pos2"],Animations[name]["pos3"],Animations[name]["pos4"],Animations[name]["pos5"],Animations[name]["pos6"])
                        elseif Animations[name]["prop"] then
                            TriggerEvent("vrp:createObjects",Animations[name]["dict"],Animations[name]["anim"],Animations[name]["prop"],Animations[name]["flag"],Animations[name]["hand"])
                        elseif Animations[name]["dict"] then
                            vRP.playAnim(Animations[name]["walk"],{Animations[name]["dict"],Animations[name]["anim"]},Animations[name]["loop"])
                        else
                            vRP.playAnim(false,{ task = Animations[name]["anim"] },false)
                        end
                    end

                    if not sync then
                        if Animations[name]["target"] then
                            TriggerServerEvent("anim:sendRequest",name)
                        end
                    end
				else
					if IsPedInAnyVehicle(Ped) and Animations[name]["cars"] then
						local vehicle = GetVehiclePedIsUsing(Ped)
                        
						if (GetPedInVehicleSeat(vehicle,-1) == Ped or GetPedInVehicleSeat(vehicle,1) == Ped) and name == "sexo4" then
							vRP.playAnim(Animations[name]["walk"],{Animations[name]["dict"],Animations[name]["anim"]},Animations[name]["loop"])
						elseif (GetPedInVehicleSeat(vehicle,0) == Ped or GetPedInVehicleSeat(vehicle,2) == Ped) and (name == "sexo5" or name == "sexo6") then
							vRP.playAnim(Animations[name]["walk"],{Animations[name]["dict"],Animations[name]["anim"]},Animations[name]["loop"])
						elseif name == "hotwired" then
							vRP.playAnim(Animations[name]["walk"],{Animations[name]["dict"],Animations[name]["anim"]},Animations[name]["loop"])
						end
					end
				end
                if not animTooltip then
                    TriggerEvent("keyText:open", "F6", _t("exitAnimation"))
                    animTooltip = true
                end
			end
		end
	end
end)
-----------------------------------------------------------------------------------------------------------------------------------------
-- THREADBINOCULOS
-----------------------------------------------------------------------------------------------------------------------------------------
CreateThread(function()
	while true do
		local TimeDistance = 999
		if (binoculos or cameras) then
			TimeDistance = 1

			local Ped = PlayerPedId()
			local scaleform = RequestScaleformMovie("BINOCULARS")
			while not HasScaleformMovieLoaded(scaleform) do
				Wait(1)
			end

			local cam = CreateCam("DEFAULT_SCRIPTED_FLY_CAMERA",true)
			AttachCamToEntity(cam,Ped,0.0,0.0,1.0,true)
			SetCamRot(cam,0.0,0.0,GetEntityHeading(Ped))
			SetCamFov(cam,fov)
			RenderScriptCams(true,false,0,1,0)

			while (binoculos or cameras) and true do
				Wait(1)

				local zoomvalue = (1.0 / (fov_max - fov_min)) * (fov - fov_min)
				CheckInputRotation(cam,zoomvalue)
				HandleZoom(cam)

				if binoculos then
					DrawScaleformMovieFullscreen(scaleform,255,255,255,255)
				end

				if IsPedArmed(PlayerPedId(),6) then
					TriggerEvent("inventory:Cancel")
					binoculos = false
					cameras = false
				end
			end

			fov = (fov_max + fov_min) * 0.5
			RenderScriptCams(false,false,0,1,0)
			SetScaleformMovieAsNoLongerNeeded(scaleform)
			DestroyCam(cam,false)
			SetNightvision(false)
			SetSeethrough(false)
		end

		Wait(TimeDistance)
	end
end)
